// `pnpm brand:sync`: generate packages/ui's tokens and mascot art from the brand kit in brand/
// (read-only), and copy the kit files other packages need. Run it after the kit changes; never edit
// the generated files by hand.
//
// Role tokens (surface, primary, link...) come from brand/DESIGN.md section 2 and are written here as
// references to the kit's palette in brand/luci-tokens.json, so no colour exists outside the kit.
// Dark roles follow DESIGN.md's "Dark surfaces" line, filled in from the same palette.
import { copyFileSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const brand = join(root, 'brand');
const ui = join(root, 'packages/ui/src');
const kit = JSON.parse(readFileSync(join(brand, 'luci-tokens.json'), 'utf8'));
const HEADER = '/* Generated by scripts/brand-sync.mjs from brand/. Do not edit: run `pnpm brand:sync`. */';

const write = (file, text) => { mkdirSync(dirname(file), { recursive: true }); writeFileSync(file, text, 'utf8'); };
const copy = (from, to) => { mkdirSync(dirname(to), { recursive: true }); copyFileSync(from, to); };

// --- Palette: --luci-color-<scale>-<step>, straight from the kit
const palette = {};
for (const [scale, steps] of Object.entries(kit.color)) {
  if (scale === 'roles') continue;
  for (const [step, hex] of Object.entries(steps)) palette[`${scale}-${step}`] = hex;
}
const pal = (ref) => {
  if (!(ref in palette)) throw new Error(`brand-sync: ${ref} is not in brand/luci-tokens.json`);
  return `var(--luci-color-${ref})`;
};
/** A kit colour at an opacity (DESIGN.md writes these as rgba of Charcoal or Muzzle White). */
const alpha = (ref, pct) => `color-mix(in srgb, ${pal(ref)} ${pct}%, transparent)`;

// --- Roles, light (DESIGN.md section 2 and 6)
const light = {
  surface: pal('muzzle-50'),
  'surface-raised': pal('muzzle-0'),
  'surface-sunken': pal('muzzle-100'),
  ink: pal('muzzle-900'),
  'ink-secondary': pal('muzzle-600'),
  'ink-disabled': pal('muzzle-400'),
  primary: pal('ginger-500'),
  'on-primary': pal('muzzle-900'),
  'primary-hover': pal('ginger-600'),
  'primary-soft': pal('ginger-100'),
  link: pal('ginger-700'),
  accent: pal('collar-lime-500'),
  'on-accent': pal('muzzle-900'),
  success: pal('success-700'), 'success-bg': pal('success-100'),
  warning: pal('warning-700'), 'warning-bg': pal('warning-100'),
  danger: pal('danger-700'), 'danger-bg': pal('danger-100'),
  // DESIGN.md section 6, danger button hover: the one fill the kit gives as a literal value
  'danger-hover': '#FFD3CD',
  info: pal('info-700'), 'info-bg': pal('info-100'),
  'secondary-hover': pal('muzzle-100'),
  'ghost-hover': alpha('muzzle-900', 6),
  'stroke-subtle': alpha('muzzle-900', 12),
  'stroke-muzzle': pal('muzzle-200'),
  'stroke-strong': alpha('muzzle-900', 24),
  focus: pal('muzzle-900')
};
// --- Roles, dark: Charcoal surface, Muzzle White text, #C2BCB8 secondary, ginger-400 accents
const dark = {
  ...light,
  surface: pal('muzzle-900'),
  'surface-raised': pal('muzzle-800'),
  // On Charcoal a tint reads only when it is lighter: sunken areas use the raised step too
  'surface-sunken': pal('muzzle-800'),
  ink: pal('muzzle-50'),
  'ink-secondary': pal('muzzle-300'),
  'ink-disabled': pal('muzzle-500'),
  primary: pal('ginger-400'),
  'primary-hover': pal('ginger-300'),
  'primary-soft': alpha('ginger-400', 18),
  link: pal('ginger-300'),
  'secondary-hover': pal('muzzle-700'),
  'ghost-hover': alpha('muzzle-50', 8),
  'stroke-subtle': alpha('muzzle-50', 16),
  'stroke-muzzle': pal('muzzle-700'),
  'stroke-strong': alpha('muzzle-50', 28),
  focus: pal('muzzle-50')
};
// --- The on-page toolbar pill is Charcoal in both themes (DESIGN.md section 6, On-page toolbar)
const bar = {
  bar: pal('muzzle-900'),
  'bar-ink': pal('muzzle-50'),
  'bar-ink-secondary': pal('muzzle-300'),
  // A hover a person can see on Charcoal (muzzle-700), clearly short of the ginger-400 active fill
  'bar-hover': pal('muzzle-700'),
  'bar-stroke': alpha('muzzle-50', 16),
  'tool-active': pal('ginger-400'),
  'on-tool-active': pal('muzzle-900')
};
// --- Page overlays Luci draws over the host page while picking and measuring (not components)
const overlay = {
  'pick': pal('ginger-500'),
  'pick-fill': alpha('ginger-500', 14),
  'pick-blocked': pal('danger-700'),
  'pick-blocked-fill': alpha('muzzle-500', 35),
  'pad-fill': alpha('collar-lime-500', 35),
  'margin-fill': alpha('ginger-300', 35),
  'insert': pal('nose-pink-500'),
  'insert-fill': alpha('nose-pink-500', 16),
  'insert-ink': pal('nose-pink-100')
};

const px = (n) => `${n}px`;
const other = {};
for (const [k, v] of Object.entries(kit.radius)) other[`radius-${k}`] = px(v);
for (const v of kit.space) other[`space-${v}`] = px(v);
// The kit's font stacks, with Luci's bundled copy of each family first (see Fonts below)
const bundled = (stack) => stack.replace(/'?(Fredoka|Inter|JetBrains Mono)'?/g, (_m, name) => `"Luci ${name}", ${name.includes(' ') ? `'${name}'` : name}`);
other['font-display'] = bundled(kit.font.display);
other['font-body'] = bundled(kit.font.body);
other['font-code'] = bundled(kit.font.code);
for (const [k, [size, line, weight]] of Object.entries(kit.type)) {
  other[`type-${k}-size`] = px(size);
  other[`type-${k}-line`] = px(line);
  other[`type-${k}-weight`] = String(weight);
}
other['shadow-float'] = kit.shadow.float;
other['motion-fast'] = kit.motion.fast;
other['motion-base'] = kit.motion.base;
other['motion-exit'] = kit.motion.exit;
for (const [k, v] of Object.entries(kit.size)) other[`size-${k.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`)}`] = px(v);

const decls = (obj, prefix, indent = '  ') => Object.entries(obj).map(([k, v]) => `${indent}--luci-${prefix}${k}: ${v};`).join('\n');
const darkBlock = decls(dark, 'color-', '    ');
const tokensCss = (selector) => `${HEADER}
${selector} {
${decls(palette, 'color-')}
${decls(other, '')}
${decls(light, 'color-')}
${decls(bar, 'color-')}
${decls(overlay, 'color-')}
}
@media (prefers-color-scheme: dark) {
  .luci-theme:not([data-theme="light"]) {
${darkBlock}
  }
}
.luci-theme[data-theme="dark"] {
${decls(dark, 'color-')}
}
`;

write(join(ui, 'tokens.css'), tokensCss(':root, :host'));
const json = (o) => JSON.stringify(o, null, 2);
write(join(ui, 'tokens.ts'), `${HEADER}
/** The kit's palette, by scale and step (brand/luci-tokens.json). */
export const PALETTE = ${json(palette)} as const;

/** Role tokens: the CSS each role resolves to, light and dark (brand/DESIGN.md section 2). */
export const ROLES_LIGHT = ${json(light)} as const;
export const ROLES_DARK = ${json(dark)} as const;
export const ROLES_BAR = ${json(bar)} as const;
export const ROLES_OVERLAY = ${json(overlay)} as const;

export const RADIUS = ${json(kit.radius)} as const;
export const SPACE = ${json(kit.space)} as const;
export const FONT = ${json(kit.font)} as const;
export const TYPE = ${json(kit.type)} as const;
export const MOTION = ${json(kit.motion)} as const;
export const SHADOW = ${json(kit.shadow)} as const;
export const SIZE = ${json(kit.size)} as const;

/**
 * Every token as CSS custom properties, for a shadow root (declared on :host, since the host page's
 * variables never reach inside). Put class "luci-theme" and data-theme="system|light|dark" on the
 * surface's root element to switch themes.
 */
export const TOKENS_CSS = ${JSON.stringify(tokensCss(':host, :root'))};
`);

// --- Mascot and logo art: the kit's SVGs as strings, unchanged
const svgDir = (dir) => Object.fromEntries(readdirSync(join(brand, dir)).filter(f => f.endsWith('.svg')).sort()
  .map(f => [f.replace(/^luci-/, '').replace(/\.svg$/, ''), readFileSync(join(brand, dir, f), 'utf8').trim()]));
const layered = svgDir('layered');
const poses = Object.fromEntries(Object.entries(layered).filter(([k]) => !k.startsWith('face-')));
const faces = Object.fromEntries(Object.entries(layered).filter(([k]) => k.startsWith('face-')).map(([k, v]) => [k.slice(5), v]));
const logos = svgDir('logo');
const animations = readFileSync(join(brand, 'luci-animations.css'), 'utf8').trim();
for (const f of readdirSync(join(brand, 'layered'))) copy(join(brand, 'layered', f), join(ui, 'mascot', f));
copy(join(brand, 'luci-animations.css'), join(ui, 'mascot/luci-animations.css'));
write(join(ui, 'mascot/art.ts'), `${HEADER}
/** Layered mascot poses (brand/layered/), inline so luci-animations.css can move their named parts. */
export const POSE_SVG = ${json(poses)} as const;
/** Small faces for toasts and inline messages (brand/layered/luci-face-*.svg). */
export const FACE_SVG = ${json(faces)} as const;
/** Logo files (brand/logo/*.svg). */
export const LOGO_SVG = ${json(logos)} as const;
/** brand/luci-animations.css */
export const ANIMATIONS_CSS = ${JSON.stringify(animations)};
`);

// --- Icons: the approved Lucide icons under Luci names (brand/luci-icons.json, DESIGN.md section 7).
// The only file allowed to import from lucide-preact; "menu" is Luci's head, not a Lucide icon.
const iconKit = JSON.parse(readFileSync(join(brand, 'luci-icons.json'), 'utf8'));
const pascal = (s) => s.split('-').map(p => p[0].toUpperCase() + p.slice(1)).join('');
const icons = Object.entries(iconKit.icons).filter(([, v]) => v.lucide);
write(join(ui, 'icons.ts'), `${HEADER}
// The approved icons (brand/luci-icons.json). Import icons from here only, never from ${iconKit.packages.preact}.
export {
${icons.map(([name, v]) => `  ${pascal(v.lucide)} as Icon${pascal(name)}`).join(',\n')}
} from '${iconKit.packages.preact}';
export type { LucideIcon } from '${iconKit.packages.preact}';

/** Luci name to Lucide name, as the kit lists them. */
export const ICON_NAMES = ${json(Object.fromEntries(icons.map(([name, v]) => [name, v.lucide])))} as const;
/** Stroke, colour and sizes (px) for every icon. */
export const ICON_STYLE = ${json(iconKit.style)} as const;
/** Approved icons that are files in the kit, not Lucide (brand/icons/): inline SVG, currentColor. */
export const ICON_SVG = ${json(Object.fromEntries(Object.entries(iconKit.icons)
  .filter(([, v]) => v.file && v.file.startsWith('icons/'))
  .map(([name, v]) => [name, readFileSync(join(brand, v.file), 'utf8').trim()])))} as const;
`);

// --- Fonts: the kit's three families, self-hosted (SIL OFL; CLAUDE-CODE-GUIDE.md section 4). The
// woff2 files live in packages/ui/src/fonts/ with their licences; here they become bytes the
// toolbar registers with the FontFace API under "Luci ..." names (no fetch, so a page's CSP can't
// block them, and they never clash with the page's own fonts).
const FONTS = [
  { family: 'Luci Fredoka', kit: 'Fredoka', file: 'fredoka-latin-wght.woff2', weight: '300 700' },
  { family: 'Luci Inter', kit: 'Inter', file: 'inter-latin-wght.woff2', weight: '100 900' },
  { family: 'Luci JetBrains Mono', kit: 'JetBrains Mono', file: 'jetbrains-mono-latin-wght.woff2', weight: '100 800' }
];
write(join(ui, 'fonts.data.ts'), `${HEADER}
/** The bundled fonts as base64 woff2 (packages/ui/src/fonts/, SIL Open Font License). */
export const FONT_FILES = ${json(FONTS.map(f => ({ family: f.family, weight: f.weight, file: f.file, woff2: readFileSync(join(ui, 'fonts', f.file)).toString('base64') })))} as const;
`);
for (const f of FONTS) copy(join(ui, 'fonts', f.file), join(root, 'packages/extension/public/fonts', f.file));

// --- Extension icons (brand/favicon/), and the logo for its help page
copy(join(brand, 'favicon/icon-192.png'), join(root, 'packages/extension/public/icon/192.png'));
copy(join(brand, 'favicon/icon-512.png'), join(root, 'packages/extension/public/icon/512.png'));
copy(join(brand, 'favicon/favicon.svg'), join(root, 'packages/extension/public/favicon.svg'));
copy(join(brand, 'logo/luci-logo-horizontal.svg'), join(root, 'packages/extension/public/luci-logo-horizontal.svg'));
copy(join(brand, 'logo/luci-logo-horizontal-dark.svg'), join(root, 'packages/extension/public/luci-logo-horizontal-dark.svg'));
copy(join(brand, 'animated/luci-sit-animated.svg'), join(root, 'packages/extension/public/luci-sit-animated.svg'));
copy(join(ui, 'tokens.css'), join(root, 'packages/extension/public/luci-tokens.css'));

console.log(`brand-sync: ${Object.keys(palette).length} colours, ${Object.keys(poses).length} poses, ${Object.keys(faces).length} faces, ${Object.keys(logos).length} logos`);
